  1	package deploy
  2	
  3	import (
  4		"fmt"
  5		"io/fs"
  6		"os"
  7		"path"
  8		"path/filepath"
  9		"slices"
 10		"strings"
 11	
 12		"github.com/integrio-intropy/intropy-cli/internal/gitops"
 13		"github.com/integrio-intropy/intropy-cli/internal/kustomize"
 14	)
 15	
 16	// What scaffolding does to one file.
 17	const (
 18		// ActionCreate: the file is not in the repository yet.
 19		ActionCreate = "create"
 20	
 21		// ActionIdentical: already there, byte for byte. Not written, and not
 22		// counted as a change — this is what makes a re-run a genuine no-op.
 23		ActionIdentical = "identical"
 24	
 25		// ActionSkipExists: already there and different. Left alone, because a
 26		// human or a previous deploy owns it now. Reported so the difference is
 27		// visible rather than silently ignored.
 28		ActionSkipExists = "skip-exists"
 29	
 30		// ActionOverwrite: already there and different, and --force was given.
 31		ActionOverwrite = "overwrite"
 32	)
 33	
 34	// FileAction is one staged file's fate.
 35	type FileAction struct {
 36		// Rel is relative to the repository root, slash-separated.
 37		Rel    string `json:"path"`
 38		Action string `json:"action"`
 39	}
 40	
 41	// Writes reports whether the action puts bytes on disk.
 42	func (a FileAction) Writes() bool {
 43		return a.Action == ActionCreate || a.Action == ActionOverwrite
 44	}
 45	
 46	// stageRels lists every file a render produced, relative to the staging root and
 47	// slash-separated, sorted so a plan reads in tree order.
 48	func stageRels(stagingDir string) ([]string, error) {
 49		var rels []string
 50		err := filepath.WalkDir(stagingDir, func(p string, d fs.DirEntry, err error) error {
 51			if err != nil {
 52				return err
 53			}
 54			if d.IsDir() {
 55				return nil
 56			}
 57			rel, err := filepath.Rel(stagingDir, p)
 58			if err != nil {
 59				return err
 60			}
 61			rels = append(rels, filepath.ToSlash(rel))
 62			return nil
 63		})
 64		if err != nil {
 65			return nil, fmt.Errorf("read staged manifests: %w", err)
 66		}
 67		slices.Sort(rels)
 68		return rels, nil
 69	}
 70	
 71	// classifyStaged decides what to do with each staged file, given what is already
 72	// in the repository.
 73	//
 74	// Rendering straight into the tree is never an option: the renderer overwrites,
 75	// and an overlay holds digests intropy deploy pinned. Staging first and
 76	// classifying second is what makes this command additive — a system gains a
 77	// component and only that subtree is new, while everything a human has since
 78	// edited is left exactly as it is.
 79	func classifyStaged(stagingDir, destRoot string, rels []string, force bool) ([]FileAction, error) {
 80		actions := make([]FileAction, 0, len(rels))
 81		for _, rel := range rels {
 82			staged := filepath.Join(stagingDir, filepath.FromSlash(rel))
 83			existing := filepath.Join(destRoot, filepath.FromSlash(rel))
 84	
 85			current, err := os.ReadFile(existing)
 86			if err != nil {
 87				if !os.IsNotExist(err) {
 88					return nil, fmt.Errorf("read %s: %w", rel, err)
 89				}
 90				actions = append(actions, FileAction{Rel: rel, Action: ActionCreate})
 91				continue
 92			}
 93			next, err := os.ReadFile(staged)
 94			if err != nil {
 95				return nil, fmt.Errorf("read staged %s: %w", rel, err)
 96			}
 97	
 98			switch {
 99			case string(current) == string(next):
100				actions = append(actions, FileAction{Rel: rel, Action: ActionIdentical})
101			case force:
102				actions = append(actions, FileAction{Rel: rel, Action: ActionOverwrite})
103			default:
104				actions = append(actions, FileAction{Rel: rel, Action: ActionSkipExists})
105			}
106		}
107		return actions, nil
108	}
109	
110	// assertForceIsSafe refuses a --force that would overwrite a pinned overlay.
111	//
112	// kustomize records a digest in the overlay's kustomization file, so replacing
113	// one with a freshly rendered skeleton un-deploys whatever that environment is
114	// running. There is no version of that a user meant to ask for, so this is a
115	// hard refusal rather than a warning, and it names every file so the fix is
116	// obvious.
117	func assertForceIsSafe(destRoot string, actions []FileAction) error {
118		var pinned []string
119		for _, a := range actions {
120			if a.Action != ActionOverwrite || !isKustomizationFile(a.Rel) {
121				continue
122			}
123			k, _, err := kustomize.ReadKustomization(filepath.Join(destRoot, filepath.FromSlash(path.Dir(a.Rel))))
124			if err != nil {
125				// Unreadable or absent: nothing to protect, and the render will
126				// report a real problem if there is one.
127				continue
128			}
129			for _, img := range k.Images {
130				if img.Digest != "" {
131					pinned = append(pinned, fmt.Sprintf("  %s pins %s at %s", a.Rel, img.Name, img.Digest))
132					break
133				}
134			}
135		}
136		if len(pinned) == 0 {
137			return nil
138		}
139		return fmt.Errorf("--force would overwrite %d overlay%s that pin a digest, un-deploying what they run:\n%s\n\nRemove those paths from the scaffold, or delete the overlay deliberately first.",
140			len(pinned), plural(len(pinned)), strings.Join(pinned, "\n"))
141	}
142	
143	func isKustomizationFile(rel string) bool {
144		return slices.Contains(kustomize.KustomizationFileNames, path.Base(rel))
145	}
146	
147	// applyStaged copies the staged files the actions say to write.
148	//
149	// Nothing is written until every action has been classified, so a failure part
150	// way through classification leaves the repository untouched.
151	func applyStaged(stagingDir, destRoot string, actions []FileAction) ([]string, error) {
152		var written []string
153		for _, a := range actions {
154			if !a.Writes() {
155				continue
156			}
157			src := filepath.Join(stagingDir, filepath.FromSlash(a.Rel))
158			dst := filepath.Join(destRoot, filepath.FromSlash(a.Rel))
159			if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
160				return written, fmt.Errorf("create %s: %w", path.Dir(a.Rel), err)
161			}
162			data, err := os.ReadFile(src)
163			if err != nil {
164				return written, fmt.Errorf("read staged %s: %w", a.Rel, err)
165			}
166			if err := os.WriteFile(dst, data, 0o644); err != nil {
167				return written, fmt.Errorf("write %s: %w", a.Rel, err)
168			}
169			written = append(written, a.Rel)
170		}
171		return written, nil
172	}
173	
174	// OverlaysSegment is the skeleton directory whose contents may legitimately
175	// differ between environments.
176	const OverlaysSegment = "overlays/"
177	
178	// mergeRendered folds one environment's render into the unit's staged tree.
179	//
180	// A skeleton is rendered once per environment, because the renderer has no way to
181	// emit one overlays/<env>/ directory per value — paths are templated, not
182	// iterated. Everything outside overlays/ must therefore come out identical on
183	// every pass, and this is where that is enforced: a file that differs between two
184	// environments means the author used an environment-varying value somewhere it
185	// does not belong, and silently keeping the last pass would be a tree whose base/
186	// only matches one environment.
187	func mergeRendered(from, into, env string) error {
188		return filepath.WalkDir(from, func(p string, d fs.DirEntry, err error) error {
189			if err != nil {
190				return err
191			}
192			rel, err := filepath.Rel(from, p)
193			if err != nil {
194				return err
195			}
196			if rel == "." {
197				return nil
198			}
199			target := filepath.Join(into, rel)
200			if d.IsDir() {
201				return os.MkdirAll(target, 0o755)
202			}
203	
204			next, err := os.ReadFile(p)
205			if err != nil {
206				return err
207			}
208			if current, err := os.ReadFile(target); err == nil {
209				if string(current) == string(next) {
210					return nil
211				}
212				if !strings.HasPrefix(filepath.ToSlash(rel), OverlaysSegment) {
213					return fmt.Errorf("%s renders differently for environment %q than for an earlier one; a value that varies by environment may only be used under %s",
214						filepath.ToSlash(rel), env, OverlaysSegment)
215				}
216			}
217			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
218				return err
219			}
220			return os.WriteFile(target, next, 0o644)
221		})
222	}
223	
224	// componentRelPath is the repository-relative directory a component's manifests
225	// live in, slash-separated.
226	func componentRelPath(domain, system, component string) string {
227		return gitops.Coordinate{Domain: domain, System: system, Component: component}.RelPath()
228	}
229	
230	// summariseActions counts the actions by kind for the one-line report.
231	func summariseActions(actions []FileAction) string {
232		counts := map[string]int{}
233		for _, a := range actions {
234			counts[a.Action]++
235		}
236		var parts []string
237		for _, kind := range []string{ActionCreate, ActionOverwrite, ActionSkipExists, ActionIdentical} {
238			if n := counts[kind]; n > 0 {
239				parts = append(parts, fmt.Sprintf("%d %s", n, kind))
240			}
241		}
242		if len(parts) == 0 {
243			return "nothing to do"
244		}
245		return strings.Join(parts, ", ")
246	}
