 14		"github.com/integrio-intropy/intropy-cli/internal/command"
 15		"github.com/integrio-intropy/intropy-cli/internal/git"
 16		"github.com/integrio-intropy/intropy-cli/internal/gitops"
 17		"github.com/integrio-intropy/intropy-cli/internal/template"
 18		"github.com/integrio-intropy/intropy-cli/internal/topology"
 19	)
 20	
 21	// The templates deploy init renders. They are separate packages because they
 22	// render a different number of times — once per system, once per component —
 23	// into different directories, from different value sets.
 24	const (
 25		TemplateDeployHost      = "deploy-host"
 26		TemplateDeployComponent = "deploy-component"
 27	)
 28	
 29	// HostDirName is the component directory holding a system's shared manifests.
 30	//
 31	// A Dapr Component is namespace-scoped and every integration in a customer's
 32	// namespace shares it, so exactly one ArgoCD Application may own each one. The
 33	// system host is what gives them that owner: it has no Dockerfile and therefore
 34	// no image, which is precisely what gitops.KindShared describes.
 35	const HostDirName = "host"
 36	
 37	// initBranchPrefix namespaces the branches this command pushes.
 38	const initBranchPrefix = "deploy-init/"
 39	
 40	// runGraph is the seam tests replace to avoid a dotnet build.
 41	var runGraph = topology.RunGraph
 42	
 43	// InitOptions configures Init.
 44	//
 45	// There is no Environment: overlays are created for every environment the
 46	// repository defines unless Environments narrows it. There is no AllowDirty, no
 47	// NoWait and no Timeout either — no source working tree is read for correctness,
 48	// and nothing is synced.
 49	type InitOptions struct {
 50		// Components narrows the run to named topology components. Empty means the
 51		// whole system, host included.
 52		Components []string
 53	
 54		// Domain places the system in the GitOps tree. Unlike every other deploy
 55		// subcommand's --domain this is a destination rather than a filter. Empty is
 56		// inferred when exactly one domain already holds the system.
 57		Domain string
 58	
 59		// System overrides the topology's own system name as the tree segment.
 60		System string
 61	
 62		// Environments selects which overlays to create. Empty means every
 63		// environment in deploy.yaml.
 64		Environments []string
 65	
 66		// TopologyFile reads the record from a file instead of running the host's
 67		// graph verb; "-" reads stdin. Both the CI path and the test seam.
 68		TopologyFile string
 69	
 70		// SourceDir is where system hosts and scaffold records are discovered.
 71		SourceDir string
 72	
 73		// TemplateVersion pins the template library release.
 74		TemplateVersion string
 75	
 76		// Files, SetValues, NoInput and Stdin are the value layering, identical to
 77		// int create.
 78		Files     []string
 79		SetValues map[string]any
 80		NoInput   bool
 81		Stdin     io.Reader
 82	
 83		// PlanOnly resolves, renders and classifies, then reports without writing
 84		// anything or touching git.
 85		PlanOnly bool
 86	
 87		// Force overwrites files that already differ, subject to the pinned-digest
 88		// guard in assertForceIsSafe.
 89		Force bool
 90	
 91		GitopsRepo   string
 92		OutputFormat string
 93		Color        bool
 94		CacheRoot    string
 95	
 96		Runner     command.Runner
 97		UserAgent  string
 98		CliVersion string
 99		Stdout     io.Writer
100		Stderr     io.Writer
101	
102		// Test overrides for the template library. Production callers leave these
103		// zero-valued.
104		Owner         string
105		Repo          string
106		GitHubBaseURL string
107		HTTP          *http.Client
108	}
109	
110	func (o InitOptions) output() output {
111		return output{Format: o.OutputFormat, Color: o.Color, Stdout: o.Stdout, Stderr: o.Stderr}
112	}
113	
114	func (o InitOptions) session() sessionOptions {
115		return sessionOptions{
116			GitopsRepo: o.GitopsRepo,
117			CacheRoot:  o.CacheRoot,
118			Runner:     o.Runner,
119			Stderr:     o.Stderr,
120		}
121	}
122	
123	func (o *InitOptions) applyDefaults() {
124		if o.Runner == nil {
125			o.Runner = command.ExecRunner{}
126		}
127		if o.SourceDir == "" {
128			o.SourceDir = "."
129		}
130		if o.OutputFormat == "" {
131			o.OutputFormat = OutputPlain
132		}
133		if o.UserAgent == "" {
134			o.UserAgent = "intropy-cli"
135		}
136		if o.Stdin == nil {
137			o.Stdin = os.Stdin
138		}
139		if o.Stdout == nil {
140			o.Stdout = os.Stdout
141		}
142		if o.Stderr == nil {
143			o.Stderr = os.Stderr
144		}
145	}
146	
147	// Init scaffolds a system's manifests into the GitOps repository.
148	//
149	// The sequencing matters more than it looks. The topology is resolved *before*
150	// the session is opened, because openSession takes a non-blocking exclusive lock
151	// on the shared cached checkout and the graph verb can take minutes on a cold
152	// project — holding the lock across that would fail every colleague's deploy
153	// outright. Nothing is written until every file has been classified, and nothing
154	// is pushed to the default branch: a tree full of placeholders would be picked up
155	// by the ApplicationSet immediately.
156	func Init(ctx context.Context, opts InitOptions) error {
157		opts.applyDefaults()
158		out := opts.output()
159	
160		topo, scaffolds, err := resolveInitTopology(ctx, opts)
161		if err != nil {
162			return err
163		}
164	
165		s, err := openSession(ctx, opts.session(), "git")
166		if err != nil {
167			return err
168		}
169		defer s.Close()
170	
171		facts, err := newInitFacts(opts, s, topo, scaffolds)
172		if err != nil {
173			return err
174		}
175	
176		staging, err := os.MkdirTemp("", "intropy-deploy-init-*")
177		if err != nil {
178			return fmt.Errorf("create staging directory: %w", err)
179		}
180		defer os.RemoveAll(staging)
181	
182		libraryRef, err := renderScaffold(ctx, opts, facts, staging)
183		if err != nil {
184			return err
185		}
186		branch := initBranchPrefix + facts.Domain + "-" + facts.System
187	
188		rels, err := stageRels(staging)
189		if err != nil {
190			return err
191		}
192		actions, err := classifyStaged(staging, s.repo.Root, rels, opts.Force)
193		if err != nil {
194			return err
195		}
196		if opts.Force {
197			if err := assertForceIsSafe(s.repo.Root, actions); err != nil {
198				return err
199			}
200		}
201	
202		result := InitResult{
203			System:       facts.System,
204			Domain:       facts.Domain,
205			Host:         HostDirName,
206			Template:     libraryRef,
207			Components:   facts.ComponentNames(),
208			Files:        actions,
209			Applied:      false,
210			Placeholders: nil,
211		}
212	
213		if opts.PlanOnly {
214			// Scan the staging tree: the files are not in the repository yet, so the
215			// only place the placeholders exist is where they were rendered.
216			result.Placeholders, err = scanPlaceholders(staging, rels)
217			if err != nil {
218				return err
219			}
220			return reportInit(out, result, actions, true)
221		}
222	
223		if writes(actions) == 0 {
224			// Nothing to write, but the placeholders already in the repository are
225			// still the answer to "what is left to do here".
226			result.Placeholders, err = scanPlaceholders(s.repo.Root, rels)
227			if err != nil {
228				return err
229			}
230			return reportInit(out, result, actions, false)
231		}
232	
233		published, err := publishScaffold(ctx, opts, s.repo, publishScaffoldOptions{
234			StagingDir: staging,
235			Actions:    actions,
236			Rels:       rels,
237			Branch:     branch,
238			Facts:      facts,
239		})
240		if err != nil {
241			return err
242		}
243		result.Applied = true
244		result.Branch = branch
245		result.Revision = published.Revision
246		result.Placeholders = published.Placeholders
247	
248		return reportInit(out, result, actions, false)
249	}
250	
251	func writes(actions []FileAction) int {
252		n := 0
253		for _, a := range actions {
254			if a.Writes() {
255				n++
256			}
257		}
258		return n
259	}
260	
261	// resolveInitTopology obtains the record and the workspace's scaffold records.
262	//
263	// A file beats the graph verb: it is how CI avoids paying for a dotnet build, and
264	// how tests avoid needing dotnet at all.
265	func resolveInitTopology(ctx context.Context, opts InitOptions) (*topology.Topology, []template.ScaffoldEntry, error) {
266		scaffolds, warnings := template.ListScaffolds(opts.SourceDir)
267		for _, w := range warnings {
268			fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
269		}
270	
271		if opts.TopologyFile != "" {
272			r := opts.Stdin
273			if opts.TopologyFile != "-" {
274				f, err := os.Open(opts.TopologyFile)
275				if err != nil {
276					return nil, nil, fmt.Errorf("read --topology: %w", err)
277				}
278				defer f.Close()
279				r = f
280			}
281			topo, err := topology.Decode(r)
282			if err != nil {
283				return nil, nil, fmt.Errorf("read --topology %s: %w", opts.TopologyFile, err)
284			}
285			return topo, scaffolds, nil
286		}
287	
288		var hosts []template.ScaffoldEntry
289		for _, s := range scaffolds {
290			if s.Role == template.RoleSystemHost {
291				hosts = append(hosts, s)
292			}
293		}
294		switch len(hosts) {
295		case 0:
296			return nil, nil, fmt.Errorf("no system host found under %s; run this from a system workspace, or pass --topology with the output of `dotnet run --project <host> -- graph`", opts.SourceDir)
297		case 1:
298		default:
299			names := make([]string, 0, len(hosts))
300			for _, h := range hosts {
301				names = append(names, h.Path)
302			}
303			slices.Sort(names)
304			return nil, nil, fmt.Errorf("%s holds %d system hosts (%s); use -C to pick one, or pass --topology",
305				opts.SourceDir, len(hosts), strings.Join(names, ", "))
306		}
307	
308		// Said before starting, not after: a silent multi-minute wait reads as a hang.
309		fmt.Fprintf(opts.Stderr, "reading topology from %s (building first; this can take a minute)\n", hosts[0].Path)
310		topo, err := runGraph(ctx, hosts[0].Path)
311		if err != nil {
312			return nil, nil, fmt.Errorf("%s: %w", hosts[0].Path, err)
313		}
314		return topo, scaffolds, nil
315	}
316	
317	// initFacts is everything derived before rendering: where the manifests go, what
318	// the platform is, and the model the skeletons range over.
319	type initFacts struct {
320		Domain string
321		System string
322	
323		Environments []string
324		Registry     string
325		AppNamespace string
326		Platform     gitops.PlatformConfig
327	
328		Model     InitModel
329		Scaffolds map[string]template.ScaffoldEntry
330		Selected  []InitComponent
331	}
332	
333	func (f initFacts) ComponentNames() []string {
334		names := make([]string, 0, len(f.Selected))
335		for _, c := range f.Selected {
336			names = append(names, c.Name)
337		}
338		return names
339	}
340	
341	func newInitFacts(opts InitOptions, s *session, topo *topology.Topology, scaffolds []template.ScaffoldEntry) (initFacts, error) {
342		system := opts.System
343		if system == "" {
344			system = topo.System
345		}
346		if system == "" {
347			return initFacts{}, fmt.Errorf("the topology record names no system; pass --system")
348		}
349	
350		domain, err := resolveInitDomain(s.repo.Root, opts.Domain, system)
351		if err != nil {
352			return initFacts{}, err
353		}
354	
355		environments, err := selectEnvironments(s.deployCfg, opts.Environments)
356		if err != nil {
357			return initFacts{}, err
358		}
359	
360		model := newInitModel(topo, scaffolds)
361		selected, err := selectComponents(model, opts.Components)
362		if err != nil {
363			return initFacts{}, err
364		}
365		for _, c := range selected {
366			if c.Dir == "" {
367				fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under %s; its manifests will be generated without an appId or sourcePaths\n", c.Name, opts.SourceDir)
368			}
369		}
370	
371		return initFacts{
372			Domain:       domain,
373			System:       system,
374			Environments: environments,
375			Registry:     s.deployCfg.Registry,
376			AppNamespace: s.deployCfg.Argocd.AppNamespace,
377			Platform:     s.deployCfg.Platform,
378			Model:        model,
379			Scaffolds:    matchScaffolds(topo.Components, scaffolds),
380			Selected:     selected,
381		}, nil
382	}
383	
384	// resolveInitDomain places the system in the tree.
385	//
386	// The topology has no idea which business domain a system belongs to, so on a
387	// first run the domain has to be given. Afterwards it is inferred, which is what
388	// makes a re-run flag-free — the common case.
389	func resolveInitDomain(root, flag, system string) (string, error) {
390		if flag != "" {
391			return flag, nil
392		}
393		var found []string
394		for _, c := range gitops.ListComponents(root) {
395			if c.System == system && !slices.Contains(found, c.Domain) {
396				found = append(found, c.Domain)
397			}
398		}
399		slices.Sort(found)
400		switch len(found) {
401		case 1:
402			return found[0], nil
403		case 0:
404			return "", fmt.Errorf("--domain is required: %s is not in the repository yet, so there is no domain to infer", system)
405		default:
406			return "", fmt.Errorf("--domain is required: %s exists under %s", system, strings.Join(found, " and "))
407		}
408	}
