410	func selectEnvironments(cfg *gitops.DeployConfig, requested []string) ([]string, error) {
411		if len(requested) == 0 {
412			// Every environment, in promotion order. The ApplicationSet takes the
413			// environment from its cluster generator rather than the path, so an
414			// environment without an overlay is an Application pointing at nothing.
415			return cfg.PromotionOrder(), nil
416		}
417		for _, env := range requested {
418			if _, err := cfg.Environment(env); err != nil {
419				return nil, err
420			}
421		}
422		out := slices.Clone(requested)
423		slices.Sort(out)
424		return slices.Compact(out), nil
425	}
426	
427	func selectComponents(m InitModel, requested []string) ([]InitComponent, error) {
428		if len(requested) == 0 {
429			return m.Components, nil
430		}
431		byName := make(map[string]InitComponent, len(m.Components))
432		names := make([]string, 0, len(m.Components))
433		for _, c := range m.Components {
434			byName[c.Name] = c
435			names = append(names, c.Name)
436		}
437		var out []InitComponent
438		for _, want := range requested {
439			c, ok := byName[want]
440			if !ok {
441				return nil, fmt.Errorf("no component %q in the topology; it declares: %s", want, strings.Join(names, ", "))
442			}
443			out = append(out, c)
444		}
445		slices.SortFunc(out, func(a, b InitComponent) int { return strings.Compare(a.Name, b.Name) })
446		return out, nil
447	}
