449	// renderScaffold renders the host template once and the component template once
450	// per selected component, into a staging tree that mirrors the repository root.
451	//
452	// Staging mirrors the repository so a staged path is already the repo-relative
453	// path the classifier and the commit both need.
454	// It returns the resolved library reference so the result can record which
455	// release produced the tree a reviewer is looking at.
456	func renderScaffold(ctx context.Context, opts InitOptions, facts initFacts, staging string) (string, error) {
457		lib, err := template.FetchLibrary(ctx, template.LibraryOptions{
458			Version:       opts.TemplateVersion,
459			HTTP:          opts.HTTP,
460			UserAgent:     opts.UserAgent,
461			Stderr:        opts.Stderr,
462			Owner:         opts.Owner,
463			Repo:          opts.Repo,
464			GitHubBaseURL: opts.GitHubBaseURL,
465		})
466		if err != nil {
467			return "", err
468		}
469		defer lib.Close()
470	
471		if err := renderOne(opts, facts, lib, TemplateDeployHost, HostDirName, nil, staging); err != nil {
472			return "", err
473		}
474		for _, c := range facts.Selected {
475			comp := c
476			if err := renderOne(opts, facts, lib, TemplateDeployComponent, c.Name, &comp, staging); err != nil {
477				return "", err
478			}
479		}
480		return lib.Ref(), nil
481	}
482	
483	// renderOne renders one unit — the host, or one component — into the staging
484	// tree.
485	//
486	// The skeleton is rendered once per environment, because the renderer templates
487	// paths but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
488	// the only way to get one directory per environment. mergeRendered then enforces
489	// that everything outside overlays/ came out identical on every pass.
490	func renderOne(opts InitOptions, facts initFacts, lib *template.Library, templateName, dirName string, comp *InitComponent, staging string) error {
491		tmpl, skeleton, err := lib.Open(templateName)
492		if err != nil {
493			return err
494		}
495	
496		dest := filepath.Join(staging, filepath.FromSlash(componentRelPath(facts.Domain, facts.System, dirName)))
497		if err := os.MkdirAll(dest, 0o755); err != nil {
498			return err
499		}
500	
501		for _, env := range facts.Environments {
502			values, err := resolveInitValues(opts, facts, tmpl, dirName, comp, env)
503			if err != nil {
504				return fmt.Errorf("%s for %s: %w", templateName, dirName, err)
505			}
506	
507			pass, err := os.MkdirTemp("", "intropy-render-*")
508			if err != nil {
509				return err
510			}
511			err = template.RenderFiltered(skeleton, pass, values, tmpl.Spec.Files)
512			if err == nil {
513				err = mergeRendered(pass, dest, env)
514			}
515			os.RemoveAll(pass)
516			if err != nil {
517				return fmt.Errorf("render %s for %s (%s): %w", templateName, dirName, env, err)
518			}
519		}
520		return nil
521	}
522	
523	// resolveInitValues layers the derived facts under the user's input, then injects
524	// the structures spec.parameters cannot describe.
525	//
526	// Facts beat schema defaults; the user beats facts. That order is the whole point
527	// of ResolveLayered, and this is its first production caller.
528	func resolveInitValues(opts InitOptions, facts initFacts, tmpl *template.Template, dirName string, comp *InitComponent, env string) (map[string]any, error) {
529		base := seedDeclaredParams(tmpl, initSeeds(facts, dirName, comp))
530	
531		prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
532		values, err := template.ResolveLayered(tmpl, base, opts.Files, opts.Stdin, opts.SetValues, prompter)
533		if err != nil {
534			return nil, err
535		}
536	
537		model, err := facts.Model.asMap()
538		if err != nil {
539			return nil, err
540		}
541		reserved := map[string]any{
542			template.ReservedEnvKey:      env,
543			template.ReservedTopologyKey: model,
544			template.ReservedGitopsKey:   facts.gitopsMap(dirName, env),
545		}
546		if comp != nil {
547			componentMap, err := toMap(comp)
548			if err != nil {
549				return nil, err
550			}
551			reserved[template.ReservedComponentKey] = componentMap
552			reserved[template.ReservedScaffoldKey] = facts.scaffoldValues(comp.Name)
553		}
554		if err := template.InjectReserved(tmpl, values, reserved); err != nil {
555			return nil, err
556		}
557		return values, nil
558	}
