560	// initSeeds is every fact the CLI can derive, keyed by the parameter name a
561	// template would declare for it.
562	func initSeeds(facts initFacts, dirName string, comp *InitComponent) map[string]any {
563		seeds := map[string]any{
564			"domain":             facts.Domain,
565			"system":             facts.System,
566			"hostName":           HostDirName,
567			"registry":           facts.Registry,
568			"argocdAppNamespace": facts.AppNamespace,
569			"provider":           facts.Platform.Provider,
570			"pubsub":             facts.Platform.Pubsub,
571			"secretStore":        facts.Platform.SecretStore,
572		}
573		// Only when unambiguous. Guessing between two brokers would put the wrong
574		// name in a Component that the generated C# then fails to resolve.
575		if len(facts.Model.PubSubs) == 1 {
576			seeds["pubsubName"] = facts.Model.PubSubs[0].Name
577		}
578		if comp != nil {
579			seeds["name"] = comp.Name
580			seeds["kind"] = comp.Kind
581			seeds["appId"] = comp.AppID
582			seeds["workload"] = comp.Workload
583			if comp.Dir != "" {
584				seeds["sourceDir"] = comp.Dir
585			}
586		} else {
587			seeds["name"] = dirName
588			seeds["appId"] = dirName
589		}
590		return seeds
591	}
592	
593	// seedDeclaredParams keeps only the seeds the template declares as parameters.
594	//
595	// An undeclared key would sail past JSON Schema validation and land in the value
596	// map anyway, which is how a template silently acquires a dependency nobody
597	// documented.
598	func seedDeclaredParams(tmpl *template.Template, seeds map[string]any) map[string]any {
599		base := make(map[string]any, len(seeds))
600		for _, f := range tmpl.Fields() {
601			if v, ok := seeds[f.Name]; ok && !isBlank(v) {
602				base[f.Name] = v
603			}
604		}
605		return base
606	}
607	
608	// isBlank drops an empty derived fact so the template's own default still
609	// applies: an unset platform.pubsub must not override `default: rabbitmq`.
610	func isBlank(v any) bool {
611		s, ok := v.(string)
612		return ok && s == ""
613	}
