615	func (f initFacts) gitopsMap(component, env string) map[string]any {
616		return map[string]any{
617			"domain":             f.Domain,
618			"system":             f.System,
619			"component":          component,
620			"env":                env,
621			"host":               HostDirName,
622			"registry":           f.Registry,
623			"argocdAppNamespace": f.AppNamespace,
624			"environments":       f.Environments,
625			"platform": map[string]any{
626				"provider":    f.Platform.Provider,
627				"pubsub":      f.Platform.Pubsub,
628				"secretStore": f.Platform.SecretStore,
629			},
630		}
631	}
