633	// scaffoldValues is the component's recorded template values, or an empty map so
634	// a skeleton reading .scaffold.x never fails on a missing record.
635	func (f initFacts) scaffoldValues(component string) map[string]any {
636		if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
637			return s.Values
638		}
639		return map[string]any{}
