642	func toMap(v any) (map[string]any, error) {
643		raw, err := json.Marshal(v)
644		if err != nil {
645			return nil, err
646		}
647		var out map[string]any
648		if err := json.Unmarshal(raw, &out); err != nil {
649			return nil, err
650		}
651		return out, nil
652	}
