750	// reportInit writes the action table, then what remains to be done.
751	func reportInit(out output, result InitResult, actions []FileAction, planOnly bool) error {
752		if out.Format == OutputJSON {
753			enc := json.NewEncoder(out.Stdout)
754			enc.SetIndent("", "  ")
755			if err := enc.Encode(result); err != nil {
756				return fmt.Errorf("write JSON result: %w", err)
757			}
758			return nil
759		}
760	
761		for _, a := range actions {
762			fmt.Fprintf(out.Stdout, "  %-12s %s\n", a.Action, a.Rel)
763		}
764		fmt.Fprintf(out.Stdout, "\n%s\n", summariseActions(actions))
765	
766		switch {
767		case planOnly:
768			fmt.Fprintln(out.Stdout, "nothing written (--plan)")
769		case result.Applied:
770			fmt.Fprintf(out.Stdout, "pushed branch %s at %s\n", result.Branch, git.ShortSHA(result.Revision))
771		default:
772			fmt.Fprintln(out.Stdout, "already onboarded; nothing to write")
773		}
774	
775		if skipped := skippedPaths(actions); len(skipped) > 0 {
776			fmt.Fprintf(out.Stdout, "\n%d file%s already differ and were left alone; --force overwrites them:\n",
777				len(skipped), plural(len(skipped)))
778			for _, rel := range skipped {
779				fmt.Fprintf(out.Stdout, "  %s\n", rel)
780			}
781		}
782	
783		reportPlaceholders(out, result.Placeholders)
784		return nil
785	}
786	
787	func skippedPaths(actions []FileAction) []string {
788		var out []string
789		for _, a := range actions {
790			if a.Action == ActionSkipExists {
791				out = append(out, a.Rel)
792			}
793		}
794		return out
795	}

  1	// Package gitops models the GitOps repository: a cached, locked checkout of
  2	// it, the directory layout that locates a component, and the two contract
  3	// files (deploy.yaml and component.yaml) that describe what may be deployed
  4	// where.
  5	package gitops
  6	
  7	import (
  8		"context"
  9		"crypto/sha256"
 10		"encoding/hex"
 11		"errors"
 12		"fmt"
 13		"io/fs"
 14		"os"
 15		"path/filepath"
 16		"syscall"
 17	
 18		"github.com/integrio-intropy/intropy-cli/internal/command"
 19		"github.com/integrio-intropy/intropy-cli/internal/config"
 20		"github.com/integrio-intropy/intropy-cli/internal/git"
 21	)
 22	
 23	// Repository is a local clone of a GitOps repository, cached between runs and
 24	// held under an exclusive lock for the duration of one.
 25	type Repository struct {
 26		// Root is the checkout directory.
 27		Root string
 28	
 29		// URL is the remote this was cloned from.
 30		URL string
 31	
 32		// Branch is the remote's default branch, the branch deploys land on.
 33		Branch string
 34	
 35		Git git.Client
 36	
 37		lock *os.File
 38	}
 39	
 40	// RemoteName is the remote deploys read from and push to.
 41	const RemoteName = "origin"
 42	
 43	// Options configures Open.
 44	type Options struct {
 45		// URL is the GitOps repository to clone. Required.
 46		URL string
 47	
 48		// Runner runs git. Defaults to ExecRunner.
 49		Runner command.Runner
 50	
 51		// CacheRoot overrides where checkouts are cached. Defaults to
 52		// <user cache dir>/intropy/gitops. Injectable so tests can redirect the
 53		// cache without reaching for HOME — on macOS os.UserCacheDir derives from
 54		// it, and overriding HOME makes every git invocation pay a multi-second
 55		// penalty for a home directory that does not match the passwd entry.
 56		CacheRoot string
 57	}
 58	
 59	// Open returns a clean, up-to-date checkout of the GitOps repository.
 60	//
 61	// The checkout is cached and reused across runs, so a deploy does not pay for a
 62	// full clone every time. Because it is shared, three things are non-negotiable:
 63	// an exclusive lock for the whole run, a hard reset rather than a merge on
 64	// refresh, and removal of untracked files. A previous run killed part-way
 65	// through an edit must not be able to leak that edit into this one's commit.
 66	//
 67	// The caller must Close the result.
 68	func Open(ctx context.Context, opts Options) (*Repository, error) {
 69		if opts.URL == "" {
 70			return nil, errors.New("no GitOps repository URL")
 71		}
 72		r := opts.Runner
 73		if r == nil {
 74			r = command.ExecRunner{}
 75		}
 76		url := opts.URL
 77	
 78		cacheRoot := opts.CacheRoot
 79		if cacheRoot == "" {
 80			var err error
 81			if cacheRoot, err = defaultCacheRoot(); err != nil {
 82				return nil, err
 83			}
 84		}
 85		dir := CheckoutDir(cacheRoot, url)
 86		if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
 87			return nil, fmt.Errorf("create cache directory: %w", err)
 88		}
 89	
 90		lock, err := acquireLock(dir + ".lock")
 91		if err != nil {
 92			return nil, err
 93		}
 94	
 95		wt := &Repository{Root: dir, URL: url, lock: lock}
 96		wt.Git = git.Client{Runner: r, Dir: dir}
 97	
 98		if err := wt.refresh(ctx, r); err != nil {
 99			wt.Close()
100			return nil, err
101		}
102		return wt, nil
103	}
104	
105	func (w *Repository) refresh(ctx context.Context, r command.Runner) error {
106		if _, err := os.Stat(filepath.Join(w.Root, ".git")); err != nil {
107			if !errors.Is(err, fs.ErrNotExist) {
108				return fmt.Errorf("inspect %s: %w", w.Root, err)
109			}
110			// A directory without .git is the debris of an interrupted clone;
111			// git clone refuses to write into it, so clear it first.
112			if err := os.RemoveAll(w.Root); err != nil {
113				return fmt.Errorf("clear %s: %w", w.Root, err)
114			}
115			if err := git.Clone(ctx, r, w.URL, w.Root); err != nil {
116				return err
117			}
118		}
119	
120		branch, err := w.Git.DefaultBranch(ctx, RemoteName)
121		if err != nil {
122			return err
123		}
124		w.Branch = branch
125	
126		if err := w.Git.Fetch(ctx, RemoteName, branch); err != nil {
127			return err
128		}
129		// Hard reset, not pull: the cache has no local history worth preserving,
130		// and a merge could leave conflict markers in a file we are about to
131		// commit.
132		if err := w.Git.ResetHard(ctx, RemoteName+"/"+branch); err != nil {
133			return err
134		}
135		return w.Git.Clean(ctx)
136	}
137	
138	// Close releases the lock. The checkout itself is deliberately kept.
139	func (w *Repository) Close() error {
140		if w.lock == nil {
141			return nil
142		}
143		err := syscall.Flock(int(w.lock.Fd()), syscall.LOCK_UN)
144		if cerr := w.lock.Close(); err == nil {
145			err = cerr
146		}
147		w.lock = nil
148		return err
149	}
150	
151	func defaultCacheRoot() (string, error) {
152		base, err := os.UserCacheDir()
153		if err != nil {
154			return "", fmt.Errorf("locate cache directory: %w", err)
155		}
156		return filepath.Join(base, "intropy", "gitops"), nil
157	}
158	
159	// CachedRoot returns the existing cached checkout for the configured GitOps
160	// repository.
161	//
162	// It never clones or fetches. This backs shell completion, which has to be
163	// instant and must not touch the network — an unconfigured or not-yet-cloned
164	// repository simply yields no suggestions.
165	func CachedRoot(gitopsRepoOverride string) (string, error) {
166		cfg, err := config.Load()
167		if err != nil {
168			return "", err
169		}
170		url, err := cfg.Resolve(config.Flags{GitopsRepo: gitopsRepoOverride}).RequireGitopsRepo()
171		if err != nil {
172			return "", err
173		}
174		cacheRoot, err := defaultCacheRoot()
175		if err != nil {
176			return "", err
177		}
178		dir := CheckoutDir(cacheRoot, url)
179		if _, err := os.Stat(filepath.Join(dir, ".git")); err != nil {
180			return "", fmt.Errorf("no cached checkout of %s yet", url)
181		}
182		return dir, nil
183	}
184	
185	// CheckoutDir derives a stable cache path from the remote URL. The URL is
186	// hashed rather than sanitised because the same repository can be named several
187	// ways (SSH, HTTPS, with or without .git) and because URLs contain characters
188	// that are awkward in paths.
189	func CheckoutDir(cacheRoot, url string) string {
190		sum := sha256.Sum256([]byte(url))
191		return filepath.Join(cacheRoot, hex.EncodeToString(sum[:])[:16])
192	}
193	
194	// acquireLock takes an exclusive, non-blocking lock. Non-blocking on purpose:
195	// two concurrent deploys sharing one checkout would interleave edits, and
196	// telling the user to wait is far better than silently queueing behind a run
197	// that may itself be stuck on a network operation.
198	func acquireLock(path string) (*os.File, error) {
199		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
200		if err != nil {
201			return nil, fmt.Errorf("open lock file %s: %w", path, err)
202		}
203		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
204			f.Close()
205			if errors.Is(err, syscall.EWOULDBLOCK) {
206				return nil, fmt.Errorf("another intropy deploy is already using the cached GitOps checkout (%s); wait for it to finish", filepath.Dir(path))
207			}
208			return nil, fmt.Errorf("lock %s: %w", path, err)
209		}
210		return f, nil
211	}
  1	// Package source reads the state of a component's source repository: which
  2	// commit is being shipped, whether it is safe to ship, and which image digests
  3	// CI published for it.
  4	//
  5	// It is shared by the commands that need to name a specific build — deploy
  6	// pins those digests into an overlay, release records them in a manifest — so
  7	// it sits below both rather than inside either.
  8	package source
  9	
 10	import (
 11		"context"
 12		"fmt"
 13		"strings"
 14	
 15		"github.com/integrio-intropy/intropy-cli/internal/git"
 16		"github.com/integrio-intropy/intropy-cli/internal/gitops"
 17	)
 18	
 19	// State is what the source repository says about the commit being shipped.
 20	type State struct {
 21		// Commit is the full sha of HEAD.
 22		Commit string
 23	
 24		// Branch is the source remote's default branch, the one CI builds.
 25		Branch string
 26	
 27		// Dirty lists uncommitted changes under the component's source paths. It
 28		// is populated even when the check is waived, so callers can warn.
 29		Dirty []string
 30	}
 31	
 32	// ShortCommit abbreviates the commit for messages and commit subjects.
 33	func (s State) ShortCommit() string { return git.ShortSHA(s.Commit) }
 34	
 35	// Inspect reads the state of the source repository at dir and checks that its
 36	// HEAD is a safe thing to ship.
 37	//
 38	// Two conditions are enforced. The working tree must be clean under the
 39	// component's source paths, because CI built the pushed commit and uncommitted
 40	// changes mean the thing about to be shipped is not the thing that was just
 41	// tested. And HEAD must be an ancestor of the remote's default branch, because
 42	// an unpushed commit has no image in the registry at all.
 43	//
 44	// The cleanliness check is scoped to sourcePaths rather than applied to the
 45	// whole tree: these are monorepos holding many components, and an unrelated
 46	// dirty file elsewhere is no reason to refuse. allowDirty waives the check but
 47	// not the reporting.
 48	func Inspect(ctx context.Context, g git.Client, sourcePaths []string, allowDirty bool) (State, error) {
 49		var st State
 50	
 51		commit, err := g.HEAD(ctx)
 52		if err != nil {
 53			return st, err
 54		}
 55		st.Commit = commit
 56	
 57		dirty, err := g.Status(ctx, sourcePaths...)
 58		if err != nil {
 59			return st, err
 60		}
 61		st.Dirty = dirty
 62		if len(dirty) > 0 && !allowDirty {
 63			return st, &DirtyWorktreeError{Paths: sourcePaths, Changes: dirty}
 64		}
 65	
 66		branch, err := g.DefaultBranch(ctx, gitops.RemoteName)
 67		if err != nil {
 68			return st, err
 69		}
 70		st.Branch = branch
 71	
 72		// Fetch before reasoning about ancestry. A stale remote-tracking ref makes
 73		// a commit that was pushed yesterday look unpushed, which is the most
 74		// confusing possible version of this error.
 75		if err := g.Fetch(ctx, gitops.RemoteName, branch); err != nil {
 76			return st, err
 77		}
 78		remoteRef := gitops.RemoteName + "/" + branch
 79		pushed, err := g.IsAncestor(ctx, commit, remoteRef)
 80		if err != nil {
 81			return st, err
 82		}
 83		if !pushed {
 84			return st, &UnpushedCommitError{Commit: commit, Branch: remoteRef}
 85		}
 86	
 87		return st, nil
 88	}
 89	
 90	// DirtyWorktreeError reports uncommitted changes in the component's source.
 91	type DirtyWorktreeError struct {
 92		Paths   []string
 93		Changes []string
 94	}
 95	
 96	func (e *DirtyWorktreeError) Error() string {
 97		var b strings.Builder
 98		scope := "the working tree"
 99		if len(e.Paths) > 0 {
100			scope = strings.Join(e.Paths, ", ")
101		}
102		fmt.Fprintf(&b, "uncommitted changes under %s:", scope)
103		for _, c := range e.Changes {
104			fmt.Fprintf(&b, "\n  %s", c)
105		}
106		b.WriteString("\nCI builds the pushed commit, so this would ship something other than what you just tested.")
107		b.WriteString("\nCommit and push, or pass --allow-dirty if you are certain the image matches.")
108		return b.String()
109	}
110	
111	// UnpushedCommitError reports that HEAD has not reached the remote.
112	type UnpushedCommitError struct {
113		Commit string
114		Branch string
115	}
116	
117	func (e *UnpushedCommitError) Error() string {
118		return fmt.Sprintf("HEAD (%s) is not an ancestor of %s, so it has not been pushed; there is no image built from it yet — push first", git.ShortSHA(e.Commit), e.Branch)
119	}

  1	package release
  2	
  3	import (
  4		"context"
  5		"encoding/json"
  6		"errors"
  7		"fmt"
  8		"io"
  9		"os"
 10		"time"
 11	
 12		"github.com/integrio-intropy/intropy-cli/internal/command"
 13		"github.com/integrio-intropy/intropy-cli/internal/config"
 14		"github.com/integrio-intropy/intropy-cli/internal/git"
 15		"github.com/integrio-intropy/intropy-cli/internal/gitops"
 16		"github.com/integrio-intropy/intropy-cli/internal/source"
 17	)
 18	
 19	// now is the clock, replaced in tests so a manifest is reproducible.
 20	var now = time.Now
 21	
 22	// Create publishes an immutable release manifest and pushes an annotated git
 23	// tag. It changes no environment: what was running before is still running,
 24	// and because the version resolves the same commit it resolves the same
 25	// digests.
 26	//
 27	// Re-running for a version that already exists is safe. The existing manifest
 28	// is compared against what this run would publish; if they agree, the release
 29	// is left alone and only a missing git tag is repaired. If they disagree the
 30	// version is being reused for something else, and that is refused.
 31	func Create(ctx context.Context, opts Options) error {
 32		opts.applyDefaults()
 33	
 34		if opts.Version == "" {
 35			return errors.New("a version is required")
 36		}
 37		if err := command.RequireBinaries("git"); err != nil {
 38			return err
 39		}
 40	
 41		cfg, err := config.Load()
 42		if err != nil {
 43			return err
 44		}
 45		resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
 46		repoURL, err := resolved.RequireGitopsRepo()
 47		if err != nil {
 48			return err
 49		}
 50	
 51		fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
 52		repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
 53		if err != nil {
 54			return err
 55		}
 56		defer repo.Close()
 57	
 58		coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
 59		if err != nil {
 60			return err
 61		}
 62		comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
 63		if err != nil {
 64			return err
 65		}
 66		if len(comp.Images) == 0 {
 67			return fmt.Errorf("%s declares no images, so there is nothing to release", coord)
 68		}
 69	
 70		g := git.Client{Runner: opts.Runner, Dir: opts.SourceDir}
 71	
 72		src, err := source.Inspect(ctx, g, comp.SourcePaths, opts.AllowDirty)
 73		if err != nil {
 74			return err
 75		}
 76		if len(src.Dirty) > 0 {
 77			fmt.Fprintf(opts.Stderr, "warning: releasing with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
 78		}
 79	
 80		// Ref defaults to HEAD, which Inspect has already checked. A different ref
 81		// is resolved here and checked for reachability the same way.
 82		commit := src.Commit
 83		if opts.Ref != "HEAD" {
 84			commit, err = g.RevParse(ctx, opts.Ref)
 85			if err != nil {
 86				return fmt.Errorf("resolve --ref %s: %w", opts.Ref, err)
 87			}
 88			pushed, err := g.IsAncestor(ctx, commit, gitops.RemoteName+"/"+src.Branch)
 89			if err != nil {
 90				return err
 91			}
 92			if !pushed {
 93				return &source.UnpushedCommitError{Commit: commit, Branch: gitops.RemoteName + "/" + src.Branch}
 94			}
 95		}
 96	
 97		reg, err := NewRegistry(opts.UserAgent)
 98		if err != nil {
 99			return err
100		}
101	
102		releasesRepo := ReleasesRepo(comp.Images[0].Name)
103		ref := Ref(releasesRepo, opts.Version)
104	
105		// Look before publishing. A retry after a partial run has to recognise its
106		// own earlier work, and that is only possible while the existing manifest
107		// is still there to compare against.
108		existing, err := lookup(ctx, reg, ref)
109		if err != nil {
110			return err
111		}
112	
113		// Registry's Resolve matches source.Resolver, so no adapter is needed.
114		pins, err := source.ResolveDigests(ctx, reg, comp, commit)
115		if err != nil {
116			return err
117		}
118	
119		basis, from, err := resolveBasis(ctx, reg, g, releasesRepo, commit, opts.Since, opts.Version)
120		if err != nil {
121			return err
122		}
123	
124		var changes []Change
125		if from != "" {
126			if changes, err = Changelog(ctx, g, from, commit, comp.SourcePaths); err != nil {
127				return err
128			}
129		}
130	
131		m := &Manifest{
132			SchemaVersion: SchemaVersion,
133			Component:     coord.Component,
134			Version:       opts.Version,
135			CreatedAt:     now().UTC().Truncate(time.Second),
136			CreatedBy:     committer(),
137			Source:        Source{Commit: commit, Ref: opts.Ref, Repo: repoURL},
138			Images:        images(pins),
139			Changes:       changes,
140			ChangeBasis:   basis,
141		}
142		m.Notes = RenderNotes(changes, basis)
143	
144		result := Result{
145			Component: m.Component,
146			Version:   m.Version,
147			Ref:       ref,
148			Tag:       TagName(coord.Component, opts.Version),
149			Manifest:  m,
150		}
151	
152		switch {
153		case existing == nil:
154			digest, err := Push(ctx, reg, ref, m)
155			if err != nil {
156				return err
157			}
158			result.Digest, result.Created = digest, true
159			fmt.Fprintf(opts.Stderr, "published %s\n", ref)
160	
161		case existing.SameRelease(m):
162			// Already published, identically. Report the release that exists
163			// rather than the one this run would have built.
164			desc, err := reg.Resolve(ctx, ref)
165			if err != nil {
166				return err
167			}
168			result.Digest, result.Manifest = desc.Digest, existing
169			fmt.Fprintf(opts.Stderr, "%s already published; nothing to do\n", ref)
170	
171		default:
172			return fmt.Errorf("%s already exists and describes a different release (%s vs %s)\n"+
173				"a release is immutable: pick a new version, or delete the tag in the registry if it was published in error",
174				ref, shortSHA(existing.Source.Commit), shortSHA(m.Source.Commit))
175		}
176	
177		// Tag after publishing. The manifest is what a release is; the tag is a
178		// convenience for people reading git log, and nothing in this CLI reads it
179		// — release discovery goes through the registry. So a tag that cannot be
180		// pushed is reported and does not fail the command, and re-running repairs
181		// it against the manifest that already exists.
182		result.Tagged = tag(ctx, g, result.Tag, commit, m, opts.Stderr)
183	
184		return report(opts, result)
185	}
186	
187	// lookup reads the manifest already published at ref, if any.
188	func lookup(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
189		m, err := Pull(ctx, reg, ref)
190		switch {
191		case err == nil:
192			return m, nil
193		case errors.Is(err, ErrNotFound):
194			return nil, nil
195		case errors.Is(err, ErrNotRelease):
196			// Something else holds this tag. Publishing over it would destroy
197			// whatever it is.
198			return nil, fmt.Errorf("%s already exists and is not a release manifest: %w", ref, err)
199		default:
200			return nil, err
201		}
202	}
203	
204	// resolveBasis decides what the changelog is measured against, and returns the
205	// commit to start from. An empty from means there is nothing to measure.
206	func resolveBasis(ctx context.Context, reg Registry, g git.Client, releasesRepo, commit, since, version string) (ChangeBasis, string, error) {
207		if since != "" {
208			from, err := g.RevParse(ctx, since)
209			if err != nil {
210				return ChangeBasis{}, "", fmt.Errorf("resolve --since %s: %w", since, err)
211			}
212			ancestor, err := g.IsAncestor(ctx, from, commit)
213			if err != nil {
214				return ChangeBasis{}, "", err
215			}
216			if !ancestor {
217				return ChangeBasis{}, "", fmt.Errorf("--since %s is not an ancestor of the commit being released (%s), so there is no range between them", since, shortSHA(commit))
218			}
219			return ChangeBasis{Kind: BasisExplicit, Ref: since}, from, nil
220		}
221	
222		prev, err := PreviousRelease(ctx, reg, g, releasesRepo, commit, version)
223		if err != nil {
224			return ChangeBasis{}, "", err
225		}
226		if prev == nil {
227			// Nothing was released, so there is no prior state to diff against.
228			// The window is undefined rather than large, and saying so beats
229			// synthesising one: the first managed release of a component is
230			// usually adoption, not birth, and --since is how an operator names
231			// the point the tool cannot know.
232			return ChangeBasis{Kind: BasisInitial}, "", nil
233		}
234		return ChangeBasis{
235			Kind:    BasisRelease,
236			Version: prev.Version,
237			Commit:  prev.Source.Commit,
238		}, prev.Source.Commit, nil
239	}
240	
241	// TagName is the annotated tag for a release. Component-prefixed because these
242	// are monorepos: a bare v1.4.2 would collide the moment a second component in
243	// the same repository cut a release.
244	func TagName(component, version string) string {
245		return component + "/v" + version
246	}
247	
248	// tag creates and pushes the annotated tag, reporting whether it reached the
249	// remote. Every failure is a warning: the release is already published, and
250	// the tag is not load-bearing.
251	func tag(ctx context.Context, g git.Client, name, commit string, m *Manifest, stderr io.Writer) bool {
252		at, exists, err := g.TagCommit(ctx, name)
253		if err != nil {
254			fmt.Fprintf(stderr, "warning: could not read tag %s: %v\n", name, err)
255			return false
256		}
257	
258		switch {
259		case exists && at != commit:
260			fmt.Fprintf(stderr, "warning: tag %s already points at %s, not %s; leaving it alone\n", name, shortSHA(at), shortSHA(commit))
261			return false
262		case !exists:
263			if err := g.Tag(ctx, name, tagMessage(m), commit); err != nil {
264				fmt.Fprintf(stderr, "warning: could not create tag %s: %v\n", name, err)
265				return false
266			}
267		}
268	
269		// Pushing a tag the remote already has is a no-op, which is what makes
270		// this safe to repeat.
271		if err := g.Push(ctx, gitops.RemoteName, "refs/tags/"+name); err != nil {
272			fmt.Fprintf(stderr, "warning: release %s is published, but its git tag could not be pushed: %v\n", m.Version, err)
273			fmt.Fprintf(stderr, "         the release is valid without it; re-run to repair the tag\n")
274			return false
275		}
276		fmt.Fprintf(stderr, "tagged %s\n", name)
277		return true
278	}
279	
280	func tagMessage(m *Manifest) string {
281		return fmt.Sprintf("%s %s\n\n%s", m.Component, m.Version, m.Notes)
282	}
283	
284	func images(pins []source.Pin) []Image {
285		out := make([]Image, 0, len(pins))
286		for _, p := range pins {
287			out = append(out, Image{Name: p.Image, Digest: p.Digest})
288		}
289		return out
290	}
291	
292	func committer() string {
293		for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
294			if v := os.Getenv(key); v != "" {
295				return v
296			}
297		}
298		return ""
299	}
