301	func report(opts Options, r Result) error {
302		if opts.OutputFormat == OutputJSON {
303			enc := json.NewEncoder(opts.Stdout)
304			enc.SetIndent("", "  ")
305			return enc.Encode(r)
306		}
307		return renderCreated(opts.Stdout, r)
308	}
  1	// Package git wraps the git binary with the operations the deployment
  2	// commands need. It is deliberately narrow: only what is used, and nothing
  3	// that would tempt a caller into arbitrary git.
  4	package git
  5	
  6	import (
  7		"context"
  8		"errors"
  9		"fmt"
 10		"strings"
 11		"time"
 12	
 13		"github.com/integrio-intropy/intropy-cli/internal/command"
 14	)
 15	
 16	// Client is a typed wrapper over the git binary rooted at a working directory.
 17	type Client struct {
 18		Runner command.Runner
 19		Dir    string
 20	}
 21	
 22	func (g Client) run(ctx context.Context, args ...string) (string, error) {
 23		stdout, _, err := g.Runner.Run(ctx, g.Dir, "git", args...)
 24		return strings.TrimSpace(string(stdout)), err
 25	}
 26	
 27	// HEAD returns the full commit sha of HEAD. Full, not abbreviated: an
 28	// abbreviated sha is ambiguous as a registry tag and as an ancestry argument.
 29	func (g Client) HEAD(ctx context.Context) (string, error) {
 30		sha, err := g.run(ctx, "rev-parse", "HEAD")
 31		if err != nil {
 32			return "", fmt.Errorf("resolve HEAD: %w", err)
 33		}
 34		return sha, nil
 35	}
 36	
 37	// Status returns porcelain status lines limited to paths, or to the whole tree
 38	// when no paths are given.
 39	//
 40	// Untracked files are listed individually rather than collapsed to their
 41	// directory: these lines are shown to the user when a deploy is refused, and
 42	// "component/" is a much less useful answer than the files that are actually
 43	// uncommitted.
 44	func (g Client) Status(ctx context.Context, paths ...string) ([]string, error) {
 45		args := []string{"status", "--porcelain", "--untracked-files=all"}
 46		if len(paths) > 0 {
 47			args = append(args, "--")
 48			args = append(args, paths...)
 49		}
 50		out, err := g.run(ctx, args...)
 51		if err != nil {
 52			return nil, fmt.Errorf("read working tree status: %w", err)
 53		}
 54		if out == "" {
 55			return nil, nil
 56		}
 57		return strings.Split(out, "\n"), nil
 58	}
 59	
 60	// Fetch updates remote-tracking refs. Callers that are about to reason about
 61	// ancestry must fetch first: a stale origin/<branch> makes a pushed commit look
 62	// unpushed.
 63	func (g Client) Fetch(ctx context.Context, remote string, refspecs ...string) error {
 64		args := append([]string{"fetch", "--quiet", remote}, refspecs...)
 65		if _, err := g.run(ctx, args...); err != nil {
 66			return fmt.Errorf("fetch %s: %w", remote, err)
 67		}
 68		return nil
 69	}
 70	
 71	// DefaultBranch returns the remote's default branch name, preferring the
 72	// symbolic ref that git records at clone time and falling back to querying the
 73	// remote. Hardcoding "main" would be wrong for any repository that never
 74	// renamed from master.
 75	func (g Client) DefaultBranch(ctx context.Context, remote string) (string, error) {
 76		if out, err := g.run(ctx, "symbolic-ref", "--short", "refs/remotes/"+remote+"/HEAD"); err == nil {
 77			// refs/remotes/origin/HEAD reads back as "origin/main".
 78			if _, branch, ok := strings.Cut(out, "/"); ok && branch != "" {
 79				return branch, nil
 80			}
 81		}
 82	
 83		// Freshly cloned mirrors and worktrees created with --single-branch may
 84		// have no origin/HEAD; ask the remote directly.
 85		out, err := g.run(ctx, "ls-remote", "--symref", remote, "HEAD")
 86		if err != nil {
 87			return "", fmt.Errorf("determine default branch of %s: %w", remote, err)
 88		}
 89		for line := range strings.SplitSeq(out, "\n") {
 90			// "ref: refs/heads/main\tHEAD"
 91			rest, ok := strings.CutPrefix(strings.TrimSpace(line), "ref: refs/heads/")
 92			if !ok {
 93				continue
 94			}
 95			if branch, _, _ := strings.Cut(rest, "\t"); branch != "" {
 96				return branch, nil
 97			}
 98		}
 99		return "", fmt.Errorf("determine default branch of %s: no symref in ls-remote output", remote)
100	}
101	
102	// IsAncestor reports whether ancestor is an ancestor of descendant. Equal
103	// commits count as ancestors, matching git's own semantics.
104	func (g Client) IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error) {
105		_, err := g.run(ctx, "merge-base", "--is-ancestor", ancestor, descendant)
106		if err == nil {
107			return true, nil
108		}
109		// git exits 1 for "not an ancestor" and 128 for a bad revision, so only
110		// exit 1 may be read as a clean negative answer.
111		if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
112			return false, nil
113		}
114		return false, fmt.Errorf("check whether %s is an ancestor of %s: %w", ShortSHA(ancestor), ShortSHA(descendant), err)
115	}
116	
117	// Add stages paths.
118	func (g Client) Add(ctx context.Context, paths ...string) error {
119		args := append([]string{"add", "--"}, paths...)
120		if _, err := g.run(ctx, args...); err != nil {
121			return fmt.Errorf("stage changes: %w", err)
122		}
123		return nil
124	}
125	
126	// CheckoutPaths discards working-tree changes under paths. Always pass an
127	// explicit path: an unscoped revert would throw away anything else in the
128	// worktree, including a concurrent run's staged work.
129	func (g Client) CheckoutPaths(ctx context.Context, paths ...string) error {
130		if len(paths) == 0 {
131			return errors.New("CheckoutPaths requires at least one path")
132		}
133		args := append([]string{"checkout", "--"}, paths...)
134		if _, err := g.run(ctx, args...); err != nil {
135			return fmt.Errorf("discard changes: %w", err)
136		}
137		return nil
138	}
139	
140	// CreateBranch creates name at startPoint and checks it out, resetting it if it
141	// already exists locally.
142	//
143	// The reset is deliberate: the only local branches in a cached checkout are ones
144	// a previous run of this CLI left behind, and reusing a stale one would build a
145	// commit on top of whatever that run happened to do.
146	func (g Client) CreateBranch(ctx context.Context, name, startPoint string) error {
147		if _, err := g.run(ctx, "checkout", "-B", name, startPoint); err != nil {
148			return fmt.Errorf("create branch %s at %s: %w", name, startPoint, err)
149		}
150		return nil
151	}
152	
153	// Switch checks out an existing ref.
154	//
155	// Callers holding a shared cached checkout must switch back to the default
156	// branch when they are done: the refresh on the next Open resets whatever branch
157	// is current to the default branch's remote head, which would silently discard a
158	// feature branch's commits.
159	func (g Client) Switch(ctx context.Context, ref string) error {
160		if _, err := g.run(ctx, "checkout", ref); err != nil {
161			return fmt.Errorf("switch to %s: %w", ref, err)
162		}
163		return nil
164	}
165	
166	// ResetHard moves the branch and working tree to ref.
167	func (g Client) ResetHard(ctx context.Context, ref string) error {
168		if _, err := g.run(ctx, "reset", "--hard", ref); err != nil {
169			return fmt.Errorf("reset to %s: %w", ref, err)
170		}
171		return nil
172	}
173	
174	// Clean removes untracked files and directories.
175	func (g Client) Clean(ctx context.Context) error {
176		if _, err := g.run(ctx, "clean", "-fdq"); err != nil {
177			return fmt.Errorf("clean working tree: %w", err)
178		}
179		return nil
180	}
