182	// RevParse resolves any revision expression to a full sha.
183	func (g Client) RevParse(ctx context.Context, rev string) (string, error) {
184		sha, err := g.run(ctx, "rev-parse", rev)
185		if err != nil {
186			return "", fmt.Errorf("resolve %s: %w", rev, err)
187		}
188		return sha, nil
189	}
