191	// Clone clones url into dir. dir must not already exist.
192	func Clone(ctx context.Context, r command.Runner, url, dir string) error {
193		if _, _, err := r.Run(ctx, "", "git", "clone", "--quiet", url, dir); err != nil {
194			return fmt.Errorf("clone %s: %w", url, err)
195		}
196		return nil
197	}
