411	// Trailers returns the trailer block of a commit message as ordered pairs.
412	// Duplicate keys are preserved, since a commit may legitimately repeat one.
413	func (g Client) Trailers(ctx context.Context, rev string) ([]Trailer, error) {
414		out, err := g.run(ctx, "log", "-1", "--format=%(trailers:only=true)", rev)
415		if err != nil {
416			return nil, fmt.Errorf("read trailers of %s: %w", ShortSHA(rev), err)
417		}
418		var trailers []Trailer
419		for line := range strings.SplitSeq(out, "\n") {
420			key, value, ok := strings.Cut(strings.TrimSpace(line), ":")
421			if !ok || key == "" {
422				continue
423			}
424			trailers = append(trailers, Trailer{Key: key, Value: strings.TrimSpace(value)})
425		}
426		return trailers, nil
427	}
428	
429	// Trailer is one Key: value line from a commit message's trailer block.
430	type Trailer struct {
431		Key   string
432		Value string
433	}
434	
435	// String renders the trailer as it appears in a commit message.
436	func (t Trailer) String() string { return t.Key + ": " + t.Value }
